{-# LANGUAGE OverloadedStrings #-}
module Main (main) where
import Control.Monad (forM,unless)
import qualified Data.ByteString as B
import System.Environment (getArgs)
import System.FilePath ((</>))
import System.Posix.Files (setFileMode)
import Warlock.Backend (loadBackendConfig,configuredNotificationBusAddress)
import Data.Text (Text)

-- Startup data parsing only; no bus/socket/service operation occurs here.
cases :: [(String,B.ByteString,Either () (Maybe Text))]
cases = [
  ("old-config-unconfigured","",Right Nothing),
  ("explicit-private-address",",\"notificationBusAddress\":\"unix:path=/tmp/warlock-ux031/bus\"",Right (Just "unix:path=/tmp/warlock-ux031/bus")),
  ("explicit-guid-preserved",",\"notificationBusAddress\":\"unix:path=/tmp/warlock-ux031/bus,guid=0123456789abcdef0123456789abcdef\"",Right (Just "unix:path=/tmp/warlock-ux031/bus,guid=0123456789abcdef0123456789abcdef")),
  ("attachment-and-address",",\"applicationAttachment\":true,\"notificationBusAddress\":\"unix:path=/tmp/warlock-ux031/bus\"",Right (Just "unix:path=/tmp/warlock-ux031/bus")),
  ("old-attachment-unconfigured",",\"applicationAttachment\":true",Right Nothing),
  ("tcp-refused",",\"notificationBusAddress\":\"tcp:host=127.0.0.1,port=1\"",Left ()),
  ("abstract-refused",",\"notificationBusAddress\":\"unix:abstract=warlock\"",Left ()),
  ("list-refused",",\"notificationBusAddress\":\"unix:path=/tmp/warlock-ux031/bus;unix:path=/tmp/warlock-ux031/bus\"",Left ()),
  ("relative-refused",",\"notificationBusAddress\":\"unix:path=tmp/bus\"",Left ()),
  ("parent-refused",",\"notificationBusAddress\":\"unix:path=/tmp/../bus\"",Left ()),
  ("dot-refused",",\"notificationBusAddress\":\"unix:path=/tmp/./bus\"",Left ()),
  ("empty-segment-refused",",\"notificationBusAddress\":\"unix:path=/tmp//bus\"",Left ()),
  ("trailing-slash-refused",",\"notificationBusAddress\":\"unix:path=/tmp/bus/\"",Left ()),
  ("root-refused",",\"notificationBusAddress\":\"unix:path=/\"",Left ()),
  ("percent-refused",",\"notificationBusAddress\":\"unix:path=/tmp/%62us\"",Left ()),
  ("space-refused",",\"notificationBusAddress\":\"unix:path=/tmp/a bus\"",Left ()),
  ("control-refused",",\"notificationBusAddress\":\"unix:path=/tmp/a\\nbus\"",Left ()),
  ("unknown-key-refused",",\"notificationBusAddress\":\"unix:path=/tmp/warlock-ux031/bus,other=x\"",Left ()),
  ("guid-length-refused",",\"notificationBusAddress\":\"unix:path=/tmp/warlock-ux031/bus,guid=aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\"",Left ()),
  ("guid-uppercase-refused",",\"notificationBusAddress\":\"unix:path=/tmp/warlock-ux031/bus,guid=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"",Left ()),
  ("duplicate-guid-refused",",\"notificationBusAddress\":\"unix:path=/tmp/warlock-ux031/bus,guid=0123456789abcdef0123456789abcdef,guid=aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\"",Left ()),
  ("long-path-refused",",\"notificationBusAddress\":\"unix:\"",Left ()),
  ("null-refused",",\"notificationBusAddress\":null",Left ()),
  ("number-refused",",\"notificationBusAddress\":1",Left ()),
  ("bool-refused",",\"notificationBusAddress\":true",Left ()),
  ("array-refused",",\"notificationBusAddress\":[]",Left ()),
  ("object-refused",",\"notificationBusAddress\":{}",Left ()),
  ("unknown-config-field-refused",",\"surprise\":true",Left ()),
  ("duplicate-selection-refused",",\"notificationBusAddress\":\"unix:path=/tmp/warlock-ux031/bus\",\"notificationBusAddress\":\"unix:path=/tmp/warlock-ux031/bus\"",Left ()),
  ("trusted-path-data-boundary",",\"notificationBusAddress\":\"unix:\"",Right (Just "unix:"))
 ]

base :: B.ByteString
base = "{\"schema\":1,\"binding\":{\"lifetime\":\"1\",\"session\":\"1\",\"frontend\":\"1\"},\"deadlineMonotonicNs\":\"1\",\"ui\":{\"path\":\"/fixture\",\"device\":\"1\",\"inode\":\"1\",\"size\":\"1\",\"sha256\":\"" <> B.replicate 64 48 <> "\",\"arguments\":[],\"ancestors\":[]},\"catalogRoots\":[],\"pinsRoot\":{\"path\":\"/fixture\",\"device\":\"1\",\"inode\":\"1\"},\"locale\":\"C\""

main :: IO ()
main = do
 arguments <- getArgs
 root <- case arguments of [path] -> pure path; _ -> ioError (userError "fixed fixture root required")
 observed <- forM cases $ \(name,extra,expected) -> do
  let path = root </> (name++".json")
  B.writeFile path (base<>extra<>"}")
  setFileMode path 0o600
  decoded <- loadBackendConfig path
  let actual = case decoded of Left _ -> Left (); Right config -> Right (configuredNotificationBusAddress config)
      result = (name,actual==expected)
  print result
  pure (snd result)
 unless (length observed == 30 && and observed) (ioError (userError "notification config controls failed"))
